class Solution(db.Model):
    __tablename__ = 'solutions'

    id = db.Column(db.Integer, primary_key=True)
    code = db.Column(db.Text, nullable=False)
    language = db.Column(db.String(50), nullable=False)
    submission_time = db.Column(db.DateTime, nullable=False, default=db.func.current_timestamp())
    problem_id = db.Column(db.Integer, db.ForeignKey('problems.id'), nullable=False)
    user_id = db.Column(db.Integer, db.ForeignKey('users.id'), nullable=False)

    problem = db.relationship('Problem', backref=db.backref('solutions', lazy=True))
    user = db.relationship('User', backref=db.backref('solutions', lazy=True))

    def __repr__(self):
        return f"<Solution id={self.id} user_id={self.user_id} problem_id={self.problem_id}>"

    def save(self):
        db.session.add(self)
        db.session.commit()

    @staticmethod
    def get_by_id(solution_id):
        return Solution.query.get(solution_id)

    @staticmethod
    def get_by_problem_and_user(problem_id, user_id):
        return Solution.query.filter_by(problem_id=problem_id, user_id=user_id).first()

    @staticmethod
    def get_all_by_user(user_id):
        return Solution.query.filter_by(user_id=user_id).all()

    @staticmethod
    def get_all_by_problem(problem_id):
        return Solution.query.filter_by(problem_id=problem_id).all()

from flask import Blueprint, jsonify, request
from app.models.problem import Problem
from app.database import db

problem_bp = Blueprint('problem', __name__)

@problem_bp.route('/problems', methods=['GET'])
def get_problems():
    """
    Fetch all problems from the database.
    Returns a list of problems in JSON format.
    """
    try:
        problems = Problem.query.all()
        problem_list = [problem.to_dict() for problem in problems]
        return jsonify(problem_list), 200
    except Exception as e:
        return jsonify({"error": "An error occurred while fetching problems.", "message": str(e)}), 500

@problem_bp.route('/problems/<int:problem_id>', methods=['GET'])
def get_problem(problem_id):
    """
    Fetch a specific problem by its ID.
    Returns the problem data in JSON format.
    """
    try:
        problem = Problem.query.get(problem_id)
        if not problem:
            return jsonify({"error": "Problem not found."}), 404
        return jsonify(problem.to_dict()), 200
    except Exception as e:
        return jsonify({"error": "An error occurred while fetching the problem.", "message": str(e)}), 500

@problem_bp.route('/problems', methods=['POST'])
def create_problem():
    """
    Create a new problem in the database.
    Accepts problem data in JSON format.
    """
    try:
        data = request.json
        new_problem = Problem(**data)
        db.session.add(new_problem)
        db.session.commit()
        return jsonify(new_problem.to_dict()), 201
    except Exception as e:
        db.session.rollback()
        return jsonify({"error": "An error occurred while creating the problem.", "message": str(e)}), 500

@problem_bp.route('/problems/<int:problem_id>', methods=['PUT'])
def update_problem(problem_id):
    """
    Update an existing problem in the database.
    Accepts updated problem data in JSON format.
    """
    try:
        data = request.json
        problem = Problem.query.get(problem_id)
        if not problem:
            return jsonify({"error": "Problem not found."}), 404
        for key, value in data.items():
            setattr(problem, key, value)
        db.session.commit()
        return jsonify(problem.to_dict()), 200
    except Exception as e:
        db.session.rollback()
        return jsonify({"error": "An error occurred while updating the problem.", "message": str(e)}), 500

@problem_bp.route('/problems/<int:problem_id>', methods=['DELETE'])
def delete_problem(problem_id):
    """
    Delete a specific problem by its ID from the database.
    """
    try:
        problem = Problem.query.get(problem_id)
        if not problem:
            return jsonify({"error": "Problem not found."}), 404
        db.session.delete(problem)
        db.session.commit()
        return jsonify({"message": "Problem deleted successfully."}), 200
    except Exception as e:
        db.session.rollback()
        return jsonify({"error": "An error occurred while deleting the problem.", "message": str(e)}), 500

from flask import Blueprint, request, jsonify
from sqlalchemy.exc import SQLAlchemyError
from app.models.user import User

user_bp = Blueprint('user', __name__)

@user_bp.route('/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Fetch user by ID"""
    try:
        user = User.get_by_id(user_id)
        if user:
            return jsonify({
                'id': user.id,
                'username': user.username,
                'email': user.email
            }), 200
        else:
            return jsonify({'error': 'User not found'}), 404
    except SQLAlchemyError as e:
        return jsonify({'error': str(e)}), 500

@user_bp.route('/users', methods=['POST'])
def create_user():
    """Create a new user"""
    try:
        data = request.get_json()
        username = data.get('username')
        email = data.get('email')
        password = data.get('password')  # Assuming password is plaintext for now

        if not username or not email or not password:
            return jsonify({'error': 'Missing required fields'}), 400

        user = User(username=username, email=email, password=password)
        db.session.add(user)
        db.session.commit()

        return jsonify({
            'id': user.id,
            'username': user.username,
            'email': user.email
        }), 201
    except SQLAlchemyError as e:
        return jsonify({'error': str(e)}), 500

@user_bp.route('/users/<int:user_id>', methods=['PUT'])
def update_user(user_id):
    """Update user details"""
    try:
        data = request.get_json()
        user = User.get_by_id(user_id)

        if not user:
            return jsonify({'error': 'User not found'}), 404

        user.username = data.get('username', user.username)
        user.email = data.get('email', user.email)
        user.password = data.get('password', user.password)  # Assuming password is plaintext for now

        db.session.add(user)
        db.session.commit()

        return jsonify({
            'id': user.id,
            'username': user.username,
            'email': user.email
        }), 200
    except SQLAlchemyError as e:
        return jsonify({'error': str(e)}), 500

@user_bp.route('/users/<int:user_id>', methods=['DELETE'])
def delete_user(user_id):
    """Delete a user"""
    try:
        user = User.get_by_id(user_id)
        if not user:
            return jsonify({'error': 'User not found'}), 404

        db.session.delete(user)
        db.session.commit()  # Assuming the User model has a delete method
        return jsonify({'message': 'User deleted successfully'}), 200
    except SQLAlchemyError as e:
        return jsonify({'error': str(e)}), 500

